@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
}

abstract class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

enum Unit {
  CELSIUS
  WATT
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

class AlertMessage {}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "*" Sensor
Inhabitant "*" -- "1" SensorController
Inhabitant "0..*" -- "1" Apartment
Inhabitant "0..*" -- "1" SensorController : "has admin rights"

Sensor "1" -- "*" MeasuredValue
Sensor "1" o-- "0..1" MeasuredValue : lastValue

Sensor "1" -- "0..1" float threshold

EMonitor "1" -- "1" SensorController
EMonitor "1" -- "*" AlertMessage

SensorController "1" -- "*" AlertMessage

@enduml

